class Account {
    String owner;
    double balance;

    Account(String owner) {
        this.owner = owner;
    }

    void deposit(double amount) {
        balance += amount;
    }

    String describe() {
        return owner + ": " + balance;
    }
}

public class Main {
    public static void main(String[] args) {
        Account acc = new Account("Mia");
        acc.deposit(50);
        acc.deposit(25.5);
        System.out.println(acc.describe());
    }
}

